var o=[{title:`Definizioni`,text:`Un superset antagonista alterna schemi di movimento opposti, come una distensione seguita da un rematore. Un compound set abbina due esercizi per lo stesso gruppo muscolare. Un circuito può far ruotare cinque stazioni prima di riposare e ripetere. EMOM significa «ogni minuto all’inizio del minuto», e AMRAP significa «il maggior numero possibile di giri o ripetizioni» in un tempo stabilito.`},{title:`Perché usarli`,text:`Abbinare una spinta a una trazione fa lavorare un gruppo muscolare mentre un altro riposa, il che può far risparmiare tempo. I circuiti possono combinare lavoro di resistenza e cardio in uno spazio ridotto. Molti pensano che sviluppino più forza o muscoli, ma non è automatico; sono ancora la qualità del lavoro totale e il tuo recupero a deciderlo.`},{title:`Gestire la fatica`,text:`Uno squat pesante abbinato a uno stacco duro può peggiorare entrambi i sollevamenti, soprattutto per i principianti. Abbina esercizi che non competono troppo e riposa abbastanza a lungo da restare in controllo. I sollevamenti tecnici e i salti esplosivi spesso richiedono più recupero di quello che offre un circuito a tempo. Usa i superset quando hai poco tempo e l’abbinamento ha senso per il tuo obiettivo. Non ridurre il riposo solo per rispettare un tempo obiettivo, e salta i circuiti pieni di salti o di movimenti complicati se il tuo spazio, i limiti di rumore o il tuo corpo li escludono.`},{title:`Esempio`,text:`Fai dieci push-up inclinati controllati, poi dieci rematori con appoggio, poi riposa 90 secondi; ripeti tre volte. Un circuito di condizionamento potrebbe usare step-up, un carry leggero e la marcia, con riposo pianificato. Scegli un numero di giri che riesci a sostenere senza affrettarti verso una tecnica scadente.`}];var t=[{label:`NSCA: allenamento che fa risparmiare tempo`,url:`https://www.nsca.com/education/articles/ptq/time-efficient-training`},{label:`Position stand ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`NSCA: sicurezza e fondamenti dell’allenamento coi pesi`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`}];var a={sections:o,sources:t};export{a as default,o as sections,t as sources};